/* ------------------------------------------------------------------ *
 * Moments: the product events every surface reacts to the same way.
 *
 *   emitMoment("success")   → toast, sweep, companion "bravo", chime
 *   emitMoment("upload")    → same signature, rising notes
 *   emitMoment("delete")    → disintegration, companion shrug, soft blip
 *   emitMoment("undo")      → reverse, companion relieved
 *   emitMoment("error")     → short pulse, companion sad, low buzz
 *
 * One bus (a window CustomEvent), so a toast, a button, the companion
 * and anything else can listen without knowing each other.
 * Sound is OFF by default; haptics (vibration, mobile) are on; both are
 * viewer preferences. Motion intensity: calm / normal / expressive
 * (`data-motion` on <html>), and "reduced" when the OS asks for it.
 * ------------------------------------------------------------------ */

export type MomentName = "success" | "upload" | "delete" | "undo" | "error";

export type MomentDetail = { name: MomentName; label?: string; at: number };

export type MotionIntensity = "reduced" | "calm" | "normal" | "expressive";

export type MomentPrefs = { sound: boolean; haptics: boolean; motion: Exclude<MotionIntensity, "reduced"> };

const EVENT = "dither:moment";
const PREFS_KEY = "dither-moments";
const DEFAULT_PREFS: MomentPrefs = { sound: false, haptics: true, motion: "normal" };

/** The success signature: the chart colours, in order. Sweeps, toasts and the companion share it. */
export const SIGNATURE_STOPS = ["--chart-1", "--chart-3", "--chart-4", "--positive", "--chart-2"] as const;

export function getMomentPrefs(): MomentPrefs {
  if (typeof window === "undefined") return DEFAULT_PREFS;
  try {
    return { ...DEFAULT_PREFS, ...(JSON.parse(window.localStorage.getItem(PREFS_KEY) ?? "{}") as Partial<MomentPrefs>) };
  } catch {
    return DEFAULT_PREFS;
  }
}

export function setMomentPrefs(patch: Partial<MomentPrefs>) {
  const next = { ...getMomentPrefs(), ...patch };
  try {
    window.localStorage.setItem(PREFS_KEY, JSON.stringify(next));
  } catch {
    /* storage unavailable: lasts for this page */
  }
  applyMotionAttribute(next.motion);
  window.dispatchEvent(new CustomEvent("dither:moment-prefs", { detail: next }));
  return next;
}

/** Puts the viewer's motion intensity on <html data-motion>. Call once on load (MomentPrefsInit does). */
export function applyMotionAttribute(motion = getMomentPrefs().motion) {
  if (typeof document === "undefined") return;
  document.documentElement.dataset.motion = motion;
}

export function motionIntensity(): MotionIntensity {
  if (typeof window === "undefined") return "normal";
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return "reduced";
  const m = document.documentElement.dataset.motion as MotionIntensity | undefined;
  return m === "calm" || m === "expressive" ? m : "normal";
}

/** Duration / amplitude factor for moment animations (0 = no motion). */
export function motionFactor(): number {
  return { reduced: 0, calm: 0.7, normal: 1, expressive: 1.35 }[motionIntensity()];
}

let last: MomentDetail | null = null;

/** The latest moment (for listeners that mount because of it, like CompanionPresence). */
export function getLastMoment() {
  return last;
}

export function emitMoment(name: MomentName, label?: string) {
  if (typeof window === "undefined") return;
  const detail: MomentDetail = { name, label, at: performance.now() };
  last = detail;
  window.dispatchEvent(new CustomEvent<MomentDetail>(EVENT, { detail }));
  const prefs = getMomentPrefs();
  if (prefs.haptics) vibrate(name);
  if (prefs.sound) playSound(name);
}

export function onMoment(handler: (m: MomentDetail) => void) {
  const listener = (e: Event) => handler((e as CustomEvent<MomentDetail>).detail);
  window.addEventListener(EVENT, listener);
  return () => window.removeEventListener(EVENT, listener);
}

/* ---------- Haptics (Vibration API: Android browsers; ignored elsewhere) ---------- */
const PATTERNS: Record<MomentName, number[]> = {
  success: [12, 40, 18],
  upload: [10, 30, 10, 30, 18],
  delete: [24],
  undo: [8, 24, 8],
  error: [40, 30, 40],
};

function vibrate(name: MomentName) {
  try {
    navigator.vibrate?.(PATTERNS[name]);
  } catch {
    /* not allowed */
  }
}

/* ---------- Sound: tiny tones synthesised with Web Audio (no files) ---------- */
let audio: AudioContext | null = null;

function tone(ctx: AudioContext, freq: number, start: number, length: number, type: OscillatorType, gain: number) {
  const osc = ctx.createOscillator();
  const g = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, ctx.currentTime + start);
  g.gain.setValueAtTime(0, ctx.currentTime + start);
  g.gain.linearRampToValueAtTime(gain, ctx.currentTime + start + 0.012);
  g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + start + length);
  osc.connect(g).connect(ctx.destination);
  osc.start(ctx.currentTime + start);
  osc.stop(ctx.currentTime + start + length + 0.02);
  return osc;
}

export function playSound(name: MomentName) {
  try {
    audio ??= new AudioContext();
    const ctx = audio;
    if (ctx.state === "suspended") void ctx.resume();
    switch (name) {
      case "success":
        tone(ctx, 784, 0, 0.18, "sine", 0.06);
        tone(ctx, 1175, 0.09, 0.28, "sine", 0.05);
        break;
      case "upload":
        [523, 659, 784, 1047].forEach((f, i) => tone(ctx, f, i * 0.06, 0.22, "sine", 0.045));
        break;
      case "delete": {
        const o = tone(ctx, 420, 0, 0.16, "triangle", 0.05);
        o.frequency.exponentialRampToValueAtTime(180, ctx.currentTime + 0.16);
        break;
      }
      case "undo": {
        const o = tone(ctx, 260, 0, 0.16, "triangle", 0.045);
        o.frequency.exponentialRampToValueAtTime(520, ctx.currentTime + 0.16);
        break;
      }
      case "error":
        tone(ctx, 180, 0, 0.12, "square", 0.025);
        tone(ctx, 160, 0.14, 0.14, "square", 0.025);
        break;
    }
  } catch {
    /* audio not available */
  }
}

"use client";

import * as React from "react";

import { BAYER_4, DITHER_CELL, DITHER_DOT } from "@/registry/dither/lib/dither-tile";
import { valueNoise } from "@/registry/dither/lib/organic-field";
import { motionFactor, SIGNATURE_STOPS } from "@/registry/dither/lib/moments";
import { cn } from "@/registry/dither/lib/utils";

/* ------------------------------------------------------------------ *
 * The success signature: a band of 2px dots in the chart colours that
 * travels once across a surface (up for areas, right for buttons and
 * toasts). Shared by MomentSweep, DitherDevelop and FileDrop.
 * ------------------------------------------------------------------ */

export type SweepDirection = "up" | "right";
type RGB = [number, number, number];

const norm = typeof document !== "undefined" ? document.createElement("canvas").getContext("2d") : null;

/** Reads CSS custom properties (or colours) from `el` as RGB triples. */
export function readColors(el: Element, names: readonly string[]): RGB[] {
  const cs = getComputedStyle(el);
  return names.map((n) => {
    const raw = n.startsWith("--") ? cs.getPropertyValue(n).trim() : n;
    if (!norm) return [128, 128, 128];
    norm.fillStyle = "#808080";
    if (raw) norm.fillStyle = raw;
    const hex = String(norm.fillStyle);
    const m = /^#([0-9a-f]{6})$/i.exec(hex);
    if (m) {
      const v = parseInt(m[1], 16);
      return [v >> 16, (v >> 8) & 255, v & 255];
    }
    const r = /rgba?\(([^)]+)\)/.exec(hex);
    return r ? (r[1].split(",").slice(0, 3).map(Number) as RGB) : [128, 128, 128];
  });
}

function lerpPalette(p: RGB[], u: number): string {
  const x = ((u % 1) + 1) % 1 * (p.length - 1);
  const i = Math.floor(x), f = x - i;
  const a = p[i], b = p[Math.min(p.length - 1, i + 1)];
  return `rgb(${a[0] + (b[0] - a[0]) * f | 0},${a[1] + (b[1] - a[1]) * f | 0},${a[2] + (b[2] - a[2]) * f | 0})`;
}

export const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);

/**
 * Draws one frame of the sweep at progress `p` (0 → 1) into `ctx` (CSS px).
 * `skeleton`: grey organic dots ahead of the band (DitherDevelop); behind the band is left clear.
 */
export function drawSweep(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  p: number,
  { dir = "up", colors, skeleton, band }: { dir?: SweepDirection; colors: RGB[]; skeleton?: string; band?: number },
) {
  ctx.clearRect(0, 0, w, h);
  const L = dir === "up" ? h : w;
  const B = band ?? Math.max(24, L * 0.32);
  const front = -B + (L + 2 * B) * easeInOut(Math.min(1, Math.max(0, p)));
  const cell = DITHER_CELL, dot = DITHER_DOT, o = (cell - dot) / 2;
  const cols = Math.ceil(w / cell), rows = Math.ceil(h / cell);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = c * cell, y = r * cell;
      const t = dir === "up" ? h - y : x;
      const th = (BAYER_4[r & 3][c & 3] + 0.5) / 16;
      const k = 1 - Math.abs(t - front) / B;
      if (k > th) {
        const u = dir === "up" ? x / w : y / h;
        ctx.fillStyle = lerpPalette(colors, u * 0.85 + p * 0.5 + (t - front) / (B * 6));
        ctx.fillRect(x + o, y + o, dot, dot);
      } else if (skeleton && t > front) {
        if (valueNoise(c * 0.09, r * 0.09, 3) * 0.6 + 0.2 > th) {
          ctx.fillStyle = skeleton;
          ctx.fillRect(x + o, y + o, dot, dot);
        }
      }
    }
  }
  return front;
}

/** Sizes a canvas to its box at device pixel ratio; returns CSS size. */
export function fitCanvas(canvas: HTMLCanvasElement) {
  const r = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.max(1, Math.round(r.width * dpr));
  canvas.height = Math.max(1, Math.round(r.height * dpr));
  const ctx = canvas.getContext("2d")!;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { ctx, w: r.width, h: r.height };
}

export interface MomentSweepProps extends Omit<React.ComponentProps<"canvas">, "children"> {
  /** Plays the sweep each time this value changes to something truthy (a counter, a status, true). */
  play: unknown;
  direction?: SweepDirection;
  /** Duration in ms at normal motion (scaled by the viewer's motion intensity). */
  duration?: number;
  onDone?: () => void;
}

/** Overlay for any `relative overflow-hidden` surface: plays the signature sweep once per `play` change. */
function MomentSweep({ play, direction = "right", duration = 900, onDone, className, ...props }: MomentSweepProps) {
  const ref = React.useRef<HTMLCanvasElement>(null);
  const done = React.useRef(onDone);
  React.useEffect(() => {
    done.current = onDone;
  });

  React.useEffect(() => {
    const canvas = ref.current;
    if (!play || !canvas) return;
    const factor = motionFactor();
    if (factor === 0) {
      done.current?.();
      return;
    }
    const { ctx, w, h } = fitCanvas(canvas);
    const colors = readColors(canvas, SIGNATURE_STOPS);
    const total = duration * factor;
    const t0 = performance.now();
    let raf = 0;
    const frame = (now: number) => {
      const p = (now - t0) / total;
      drawSweep(ctx, w, h, p, { dir: direction, colors, band: direction === "right" ? Math.max(20, w * 0.22) : undefined });
      if (p < 1) raf = requestAnimationFrame(frame);
      else {
        ctx.clearRect(0, 0, w, h);
        done.current?.();
      }
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [play, direction, duration]);

  return <canvas ref={ref} aria-hidden="true" data-slot="moment-sweep" className={cn("pointer-events-none absolute inset-0 z-10 size-full", className)} {...props} />;
}

export { MomentSweep };

"use client";

import * as React from "react";

import { drawSweep, fitCanvas, readColors } from "@/registry/dither/lib/moment-sweep";
import { emitMoment, motionFactor, SIGNATURE_STOPS, type MomentName } from "@/registry/dither/lib/moments";
import { cn } from "@/registry/dither/lib/utils";

/* ------------------------------------------------------------------ *
 * DitherDevelop: content "develops" like a photo. While loading, the
 * area is grey dither (the skeleton). When `ready` turns true, the
 * signature band (chart colours, 2px dots) rises from the bottom; the
 * content appears behind it and the skeleton is eaten ahead of it.
 * Under reduced motion: a plain 200ms fade.
 * ------------------------------------------------------------------ */

export interface DitherDevelopProps extends React.ComponentProps<"div"> {
  ready: boolean;
  /** Shown while loading, over the hidden content (default: the dither skeleton only). */
  placeholder?: React.ReactNode;
  /** ms at normal motion. */
  duration?: number;
  /** Emit a moment when the reveal starts (e.g. "success" or "upload"). */
  moment?: MomentName;
  onRevealed?: () => void;
}

type Phase = "loading" | "revealing" | "done";

function DitherDevelop({ ready, placeholder, duration = 1100, moment, onRevealed, className, children, ...props }: DitherDevelopProps) {
  // Already ready on first render: no animation.
  const [phase, setPhase] = React.useState<Phase>(ready ? "done" : "loading");
  if (!ready && phase !== "loading") setPhase("loading");
  if (ready && phase === "loading") setPhase("revealing");

  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const contentRef = React.useRef<HTMLDivElement>(null);
  const revealed = React.useRef(onRevealed);
  React.useEffect(() => {
    revealed.current = onRevealed;
  });

  // Loading: static grey skeleton dots.
  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (phase !== "loading" || !canvas) return;
    const paint = () => {
      const { ctx, w, h } = fitCanvas(canvas);
      const skeleton = `rgb(${readColors(canvas, ["--border-strong"])[0].join(",")})`;
      drawSweep(ctx, w, h, 0, { colors: readColors(canvas, SIGNATURE_STOPS), skeleton });
    };
    paint();
    const ro = new ResizeObserver(paint);
    ro.observe(canvas);
    return () => ro.disconnect();
  }, [phase]);

  // Reveal.
  React.useEffect(() => {
    const canvas = canvasRef.current, content = contentRef.current;
    if (phase !== "revealing" || !canvas || !content) return;
    if (moment) emitMoment(moment);
    const factor = motionFactor();
    const finish = () => {
      content.style.maskImage = content.style.webkitMaskImage = "";
      setPhase("done");
      revealed.current?.();
    };
    if (factor === 0) {
      content.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 200, easing: "ease-out" }).onfinish = finish;
      return;
    }
    const { ctx, w, h } = fitCanvas(canvas);
    const colors = readColors(canvas, SIGNATURE_STOPS);
    const skeleton = `rgb(${readColors(canvas, ["--border-strong"])[0].join(",")})`;
    const total = duration * factor;
    const t0 = performance.now();
    let raf = 0;
    const frame = (now: number) => {
      const p = Math.min(1, (now - t0) / total);
      const front = drawSweep(ctx, w, h, p, { dir: "up", colors, skeleton });
      // Content shows behind the band: everything below (front) from the bottom, softly.
      const edge = Math.max(0, front - 8);
      const mask = `linear-gradient(to top, #000 ${edge}px, transparent ${edge + 24}px)`;
      content.style.maskImage = content.style.webkitMaskImage = mask;
      if (p < 1) raf = requestAnimationFrame(frame);
      else finish();
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [phase, duration, moment]);

  return (
    <div data-slot="dither-develop" data-phase={phase} aria-busy={phase === "loading" || undefined} className={cn("relative isolate overflow-hidden", className)} {...props}>
      <div ref={contentRef} className={cn(phase === "loading" && "invisible")} style={phase === "revealing" ? { maskImage: "linear-gradient(transparent, transparent)" } : undefined}>
        {children}
      </div>
      {phase === "loading" && placeholder ? <div className="absolute inset-0">{placeholder}</div> : null}
      {phase !== "done" ? <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 z-10 size-full" /> : null}
    </div>
  );
}

export { DitherDevelop };

"use client";

import * as React from "react";
import { createPortal } from "react-dom";

import { DITHER_CELL, DITHER_DOT } from "@/registry/dither/lib/dither-tile";
import { readColors } from "@/registry/dither/lib/moment-sweep";
import { motionFactor } from "@/registry/dither/lib/moments";
import { cn } from "@/registry/dither/lib/utils";

/* ------------------------------------------------------------------ *
 * Disintegrate: delete as a dither moment. When `gone` turns true the
 * element breaks into 2px dots (its own surface, border and text
 * colours) that drift down and fade, left to right, while its row
 * collapses; then `onGone`. Mounted with `reassemble` (after an undo),
 * the dots rise back into place and the element reappears.
 * Reduced motion: a quick fade and collapse.
 * ------------------------------------------------------------------ */

type Particle = { x: number; y: number; vx: number; vy: number; delay: number; color: string };

export interface DisintegrateProps extends React.ComponentProps<"div"> {
  gone?: boolean;
  onGone?: () => void;
  /** Play the reverse on mount (the item came back from an undo). */
  reassemble?: boolean;
  /** ms at normal motion. */
  duration?: number;
}

function makeParticles(el: HTMLElement, w: number, h: number): Particle[] {
  const cs = getComputedStyle(el);
  const inner = el.firstElementChild as HTMLElement | null;
  const ics = inner ? getComputedStyle(inner) : cs;
  const pick = (c: string) => (c && c !== "rgba(0, 0, 0, 0)" && c !== "transparent" ? c : null);
  const surface = pick(ics.backgroundColor) ?? pick(cs.backgroundColor) ?? "var(--surface)";
  const [bg, fg, border] = readColors(el, [surface, ics.color || "--foreground", "--border-strong"]);
  const out: Particle[] = [];
  const cell = DITHER_CELL;
  for (let y = 0; y < h; y += cell)
    for (let x = 0; x < w; x += cell) {
      const r = Math.random();
      if (r > 0.78) continue;
      const edge = x < cell || y < cell || x > w - cell * 2 || y > h - cell * 2;
      const c = edge ? border : r < 0.12 ? fg : bg;
      out.push({
        x,
        y,
        vx: (Math.random() - 0.3) * 40,
        vy: -20 - Math.random() * 40,
        delay: (x / w) * 0.45 + Math.random() * 0.12,
        color: `rgb(${c.join(",")})`,
      });
    }
  return out;
}

function Disintegrate({ gone = false, onGone, reassemble = false, duration = 900, className, children, ...props }: DisintegrateProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const [overlay, setOverlay] = React.useState<{ rect: DOMRect; mode: "out" | "in" } | null>(null);
  const [collapsed, setCollapsed] = React.useState(false);
  // Back from an undo: reopen the row.
  if (!gone && collapsed) setCollapsed(false);
  const goneCb = React.useRef(onGone);
  React.useEffect(() => {
    goneCb.current = onGone;
  });

  // Start: measure and open the overlay.
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (!gone) {
      el.getAnimations().forEach((a) => a.cancel());
      return;
    }
    {
      if (motionFactor() === 0) {
        el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 150, fill: "forwards" }).onfinish = () => {
          setCollapsed(true);
          setTimeout(() => goneCb.current?.(), 120);
        };
        return;
      }
      setOverlay({ rect: el.getBoundingClientRect(), mode: "out" });
    }
  }, [gone]);

  React.useEffect(() => {
    const el = ref.current;
    if (!reassemble || !el || motionFactor() === 0) return;
    // Let the row reopen first (it may have collapsed), then gather the dots into place.
    el.style.opacity = "0";
    const t = window.setTimeout(() => setOverlay({ rect: el.getBoundingClientRect(), mode: "in" }), 220);
    return () => window.clearTimeout(t);
  }, [reassemble]);

  // Run the particles.
  React.useEffect(() => {
    const canvas = canvasRef.current, el = ref.current;
    if (!overlay || !canvas || !el) return;
    const { rect, mode } = overlay;
    const pad = 80;
    const w = rect.width, h = rect.height;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = (w + pad * 2) * dpr;
    canvas.height = (h + pad * 2) * dpr;
    const ctx = canvas.getContext("2d")!;
    ctx.setTransform(dpr, 0, 0, dpr, pad, pad);
    const parts = makeParticles(el, w, h);
    const total = (duration * motionFactor()) / 1000;
    el.style.opacity = "0";
    const t0 = performance.now();
    let raf = 0;
    const frame = (now: number) => {
      const elapsed = (now - t0) / 1000;
      const T = mode === "out" ? elapsed : total - elapsed;
      ctx.clearRect(-pad, -pad, w + pad * 2, h + pad * 2);
      for (const p of parts) {
        const t = Math.max(0, T - p.delay * total);
        const life = Math.max(0, 1 - t / (total * 0.55));
        if (life <= 0) continue;
        ctx.globalAlpha = life;
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x + p.vx * t, p.y + p.vy * t + 160 * t * t, DITHER_DOT, DITHER_DOT);
      }
      ctx.globalAlpha = 1;
      if (elapsed < total) raf = requestAnimationFrame(frame);
      else {
        setOverlay(null);
        if (mode === "out") {
          setCollapsed(true);
          setTimeout(() => goneCb.current?.(), 200);
        } else el.style.opacity = "";
      }
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [overlay, duration]);

  return (
    <div
      data-slot="disintegrate"
      data-gone={gone || undefined}
      className={cn("grid transition-[grid-template-rows,opacity] duration-200 ease-(--motion-open-ease)", collapsed ? "grid-rows-[0fr]" : "grid-rows-[1fr]", className)}
      {...props}
    >
      <div ref={ref} className="min-h-0">
        {children}
      </div>
      {overlay
        ? createPortal(
            <canvas
              ref={canvasRef}
              aria-hidden="true"
              className="pointer-events-none fixed z-[90]"
              style={{ left: overlay.rect.left - 80, top: overlay.rect.top - 80, width: overlay.rect.width + 160, height: overlay.rect.height + 160 }}
            />,
            document.body,
          )
        : null}
    </div>
  );
}

export { Disintegrate };

"use client";

import * as React from "react";

import { cn } from "@/registry/dither/lib/utils";

/* ------------------------------------------------------------------ *
 * DitherText: streaming text that resolves word by word. Each new word
 * appears as sparse 2px dots (25 %), then 50 %, 75 %, then the letters
 * (masks in styles/motion.css: --dither-resolve-1…3). Words already
 * shown never animate again, so it suits token-by-token streaming.
 * Under reduced motion the words simply appear.
 * ------------------------------------------------------------------ */

export interface DitherTextProps extends Omit<React.ComponentProps<"span">, "children"> {
  /** The text so far (grows while streaming). */
  text: string;
  /** ms per word resolve. */
  duration?: number;
}

function DitherText({ text, duration = 360, className, ...props }: DitherTextProps) {
  const parts = text.split(/(\s+)/);
  return (
    <span data-slot="dither-text" className={cn("whitespace-pre-wrap", className)} {...props}>
      {parts.map((part, i) =>
        /^\s+$/.test(part) || part === "" ? (
          part
        ) : (
          <span
            key={i}
            className="motion-safe:animate-[dither-resolve_var(--dither-text-duration)_steps(1,end)_both]"
            style={{ ["--dither-text-duration" as string]: `${duration}ms`, maskSize: "16px 16px", WebkitMaskSize: "16px 16px" }}
          >
            {part}
          </span>
        ),
      )}
    </span>
  );
}

export { DitherText };

"use client";

import * as React from "react";

import { applyMotionAttribute, getMomentPrefs, setMomentPrefs, type MomentPrefs } from "@/registry/dither/lib/moments";
import { Switch } from "@/registry/dither/ui/switch";
import { ToggleGroup, ToggleGroupItem } from "@/registry/dither/ui/toggle-group";

/** Mount once (root layout): applies the viewer's motion intensity to <html data-motion>. */
export function MomentPrefsInit() {
  React.useEffect(() => applyMotionAttribute(), []);
  return null;
}

/** Viewer preferences for moments: sound (off by default), haptics, motion intensity. */
export function MomentSettings({ className }: { className?: string }) {
  const [prefs, setPrefs] = React.useState<MomentPrefs>(getMomentPrefs);
  const update = (patch: Partial<MomentPrefs>) => setPrefs(setMomentPrefs(patch));
  return (
    <div className={className ?? "flex flex-col gap-4"}>
      <Switch label="Sound" description="Short tones for success, delete, undo and errors." checked={prefs.sound} onCheckedChange={(v) => update({ sound: v })} />
      <Switch label="Haptics" description="A light vibration on phones that support it." checked={prefs.haptics} onCheckedChange={(v) => update({ haptics: v })} />
      <div className="flex flex-col gap-2">
        <span className="text-sm font-medium">Motion</span>
        <ToggleGroup type="single" variant="outline" size="sm" value={prefs.motion} onValueChange={(v) => v && update({ motion: v as MomentPrefs["motion"] })} aria-label="Motion intensity">
          <ToggleGroupItem value="calm">Calm</ToggleGroupItem>
          <ToggleGroupItem value="normal">Normal</ToggleGroupItem>
          <ToggleGroupItem value="expressive">Expressive</ToggleGroupItem>
        </ToggleGroup>
        <span className="text-xs text-muted-foreground">Your system&apos;s &quot;Reduce motion&quot; setting always wins.</span>
      </div>
    </div>
  );
}
